/**
 * Proof: the OpenPGP identity survives sign-out because the account holds it.
 *
 * Uses a real OpenPGP key generated by the same library the app uses, wrapped by the
 * same code the browser runs (`src/lib/pgpWrap.js` — imported directly, not copied), and
 * sent to the live API. The assertions are the ones that matter:
 *
 *   the server stores ciphertext, never the key;
 *   the right password unwraps it back to the identical armour;
 *   the wrong password does not;
 *   a payload that claims to be unwrapped is refused, and so is plaintext armour.
 *
 *   node scripts/proof-pgp-account.mjs
 */
import fs from 'node:fs'
import * as openpgp from 'openpgp'
import { wrapPrivateKey, unwrapPrivateKey } from '../src/lib/pgpWrap.js'

const API = 'https://mail.slothlee.xyz/api'
const USER = `pgpproof${Date.now().toString(36).slice(-5)}`
const PASSWORD = `PgpProof-${Math.random().toString(36).slice(2, 12)}`
const ADMIN_FILE = ['/tmp/admin.jwt', '/opt/data/home/.tmp/admin.jwt'].find((p) => fs.existsSync(p))
const ADMIN = ADMIN_FILE ? fs.readFileSync(ADMIN_FILE, 'utf8').trim() : ''

let passed = 0
const failures = []
function check(name, ok, detail = '') {
  if (ok) { passed += 1; console.log(`  ok   ${name}`); return }
  failures.push(`${name}${detail ? ` — ${detail}` : ''}`)
  console.log(`  FAIL ${name}${detail ? ` — ${detail}` : ''}`)
}

async function call(method, path, body, token) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  const text = await res.text()
  let json = {}
  try { json = JSON.parse(text) } catch { json = { raw: text.slice(0, 120) } }
  return { status: res.status, json }
}

async function main() {
  if (!ADMIN) throw new Error('no admin token at /tmp/admin.jwt')
  await call('DELETE', '/admin/users', { username: USER }, ADMIN)
  await call('POST', '/admin/users', { username: USER }, ADMIN)
  // The API hashes the password on the way in for credential creation, so send it raw.
  await call('POST', '/admin/users/credentials', { username: USER, password: PASSWORD }, ADMIN)
  const login = await call('POST', '/auth/login', { username: USER, password: PASSWORD })
  check('the test account can sign in', login.status === 200 && !!login.json.token, `status ${login.status}`)
  const token = login.json.token

  // ── a real identity, exactly as the app makes one ──
  const { publicKey, privateKey } = await openpgp.generateKey({
    type: 'ecc',
    curve: 'curve25519Legacy',
    userIDs: [{ name: 'Proof Account', email: `${USER}@slothlee.xyz` }],
    passphrase: 'local-passphrase',
    format: 'armored',
  })
  const fingerprint = (await openpgp.readKey({ armoredKey: publicKey })).getFingerprint().toUpperCase()

  const wrapped = await wrapPrivateKey(privateKey, PASSWORD)
  check('wrapping produces ciphertext, not the key', !wrapped.blob.includes('BEGIN PGP') && wrapped.blob.length > 200)

  const put = await call('PUT', '/user/pgpkey', {
    public_key: publicKey,
    encrypted_private_key: wrapped.blob,
    salt: wrapped.salt,
    fingerprint,
    kdf: wrapped.kdf,
    name: 'Proof Account',
    email: `${USER}@slothlee.xyz`,
  }, token)
  check('the account accepts the wrapped key', put.status === 200, `status ${put.status} ${JSON.stringify(put.json).slice(0, 90)}`)

  const got = await call('GET', '/user/pgpkey', undefined, token)
  check('the key comes back', got.status === 200 && got.json.exists === true)
  check('what comes back is still ciphertext', !String(got.json.encrypted_private_key || '').includes('BEGIN PGP'))
  check('the fingerprint round-trips', String(got.json.fingerprint || '').toUpperCase() === fingerprint)
  check('the salt round-trips, or the key could never be opened', got.json.salt === wrapped.salt)

  const recovered = await unwrapPrivateKey(
    { blob: got.json.encrypted_private_key, salt: got.json.salt, kdf: got.json.kdf },
    PASSWORD,
  )
  check('the right password recovers the identical private key', recovered.trim() === privateKey.trim())

  let wrong = ''
  try {
    await unwrapPrivateKey(
      { blob: got.json.encrypted_private_key, salt: got.json.salt, kdf: got.json.kdf },
      PASSWORD + 'x',
    )
  } catch (err) { wrong = err.code || err.message }
  check('the wrong password does not recover it', wrong === 'unwrap_failed', wrong)

  // ── refusals: this endpoint must never store a readable key ──
  const plain = await call('PUT', '/user/pgpkey', {
    public_key: publicKey, encrypted_private_key: privateKey, salt: wrapped.salt,
    fingerprint, kdf: 'none',
  }, token)
  check('a key claiming to be unwrapped is refused', plain.status === 400 && plain.json.code === 'refuse_unwrapped_private_key',
    `status ${plain.status} ${plain.json.code || ''}`)

  const noSalt = await call('PUT', '/user/pgpkey', {
    public_key: publicKey, encrypted_private_key: wrapped.blob, salt: '', fingerprint, kdf: wrapped.kdf,
  }, token)
  check('a key without its salt is refused', noSalt.status === 400, `status ${noSalt.status}`)

  const badPub = await call('PUT', '/user/pgpkey', {
    public_key: 'hello', encrypted_private_key: wrapped.blob, salt: wrapped.salt, fingerprint, kdf: wrapped.kdf,
  }, token)
  check('a non-OpenPGP public key is refused', badPub.status === 400 && badPub.json.code === 'bad_public_key',
    `status ${badPub.status} ${badPub.json.code || ''}`)

  // A second identity replaces the first: rotating a key must not leave two.
  const second = await openpgp.generateKey({
    type: 'ecc', curve: 'curve25519Legacy',
    userIDs: [{ name: 'Proof Account', email: `${USER}@slothlee.xyz` }],
    passphrase: 'local-passphrase', format: 'armored',
  })
  const secondPrint = (await openpgp.readKey({ armoredKey: second.publicKey })).getFingerprint().toUpperCase()
  const wrapped2 = await wrapPrivateKey(second.privateKey, PASSWORD)
  await call('PUT', '/user/pgpkey', {
    public_key: second.publicKey, encrypted_private_key: wrapped2.blob, salt: wrapped2.salt,
    fingerprint: secondPrint, kdf: wrapped2.kdf,
  }, token)
  const afterRotate = await call('GET', '/user/pgpkey', undefined, token)
  check('a new key replaces the old one', String(afterRotate.json.fingerprint).toUpperCase() === secondPrint)

  const del = await call('DELETE', '/user/pgpkey', undefined, token)
  check('the key can be removed', del.status === 200, `status ${del.status}`)
  const afterDelete = await call('GET', '/user/pgpkey', undefined, token)
  check('and it is gone afterwards', afterDelete.json.exists === false)

  await call('DELETE', '/admin/users', { username: USER }, ADMIN)
  const total = passed + failures.length
  console.log(`\n${passed}/${total} checks passed${failures.length ? ', FAILED:' : ''}`)
  failures.forEach((f) => console.log(`  - ${f}`))
  process.exit(failures.length ? 1 : 0)
}

main().catch(async (err) => {
  console.error('proof crashed:', err.message)
  try { await call('DELETE', '/admin/users', { username: USER }, ADMIN) } catch { /* best effort */ }
  process.exit(1)
})
